Here is the commit message:
iio: magnetometer: rm3100: add boundary check for the value
 read from RM3100_REG_TMRC

Recently, we encounter kernel crash in function rm3100_common_probe
caused by out of bound access of array rm3100_samp_rates (because of
underlying hardware failures). Add boundary check to prevent out of
bound access.

Fixes: 121354b2eceb ("iio: magnetometer: Add driver support for PNI RM3100")
Suggested-by: Zhouyi Zhou <zhouzhouyi@gmail.com>
Signed-off-by: zhili.liu <zhili.liu@ucas.com.cn>
Link: https://lore.kernel.org/r/1704157631-3814-1-git-send-email-zhouzhouyi@gmail.com
Cc: <Stable@vger.kernel.org>
Signed-off-by: Jonathan Cameron <Jonathan.Cameron@huawei.com>

Here is the root cause:
The bug is caused by an out-of-bounds access to the `rm3100_samp_rates` array due to an invalid value read from the `RM3100_REG_TMRC` register, which can occur because of underlying hardware failures. This results in a kernel crash when the driver attempts to access an index that is not valid.

Here is the patch:

 int rm3100_common_probe(struct device *dev, struct regmap *regmap, int irq)
 {
 	struct iio_dev *indio_dev;
 	struct rm3100_data *data;
 	unsigned int tmp;
 	int ret;
+	int samp_rate_index;

 	indio_dev = devm_iio_device_alloc(dev, sizeof(*data));
 	if (!indio_dev)
 		return -ENOMEM;

 	data = iio_priv(indio_dev);
 	data->regmap = regmap;

 	mutex_init(&data->lock);

 	indio_dev->name = "rm3100";
 	indio_dev->info = &rm3100_info;
 	indio_dev->channels = rm3100_channels;
 	indio_dev->num_channels = ARRAY_SIZE(rm3100_channels);
 	indio_dev->modes = INDIO_DIRECT_MODE;

 	if (!irq)
 		data->use_interrupt = false;
 	else {
 		data->use_interrupt = true;

 		init_completion(&data->measuring_done);
 		ret = devm_request_threaded_irq(dev,
 						irq,
 						rm3100_irq_handler,
 						rm3100_thread_fn,
 						IRQF_TRIGGER_HIGH |
 						IRQF_ONESHOT,
 						indio_dev->name,
 						indio_dev);
 		if (ret < 0) {
 			dev_err(dev, "request irq line failed.\n");
 			return ret;
 		}

 		data->drdy_trig = devm_iio_trigger_alloc(dev, "%s-drdy%d",
 							 indio_dev->name,
 							 iio_device_id(indio_dev));
 		if (!data->drdy_trig)
 			return -ENOMEM;

 		ret = devm_iio_trigger_register(dev, data->drdy_trig);
 		if (ret < 0)
 			return ret;
 	}

 	ret = devm_iio_triggered_buffer_setup(dev, indio_dev,
 					      &iio_pollfunc_store_time,
 					      rm3100_trigger_handler,
 					      &rm3100_buffer_ops);
 	if (ret < 0)
 		return ret;

 	ret = regmap_read(regmap, RM3100_REG_TMRC, &tmp);
 	if (ret < 0)
 		return ret;
+
+	samp_rate_index = tmp - RM3100_TMRC_OFFSET;
+	if (samp_rate_index < 0 || samp_rate_index >=  RM3100_SAMP_NUM) {
+		dev_err(dev, "The value read from RM3100_REG_TMRC is invalid!\n");
+		return -EINVAL;
+	}
 	/* Initializing max wait time, which is double conversion time. */
-	data->conversion_time = rm3100_samp_rates[tmp - RM3100_TMRC_OFFSET][2]
-				* 2;
+	data->conversion_time = rm3100_samp_rates[samp_rate_index][2] * 2;

 	/* Cycle count values may not be what we want. */
 	if ((tmp - RM3100_TMRC_OFFSET) == 0)
 		rm3100_set_cycle_count(data, 100);
 	else
 		rm3100_set_cycle_count(data, 200);

 	return devm_iio_device_register(dev, indio_dev);
 }
 EXPORT_SYMBOL_NS_GPL(rm3100_common_probe, IIO_RM3100);


